alse},{"id":"d","text":"Earth","is_correct":false}],"explanation":"Uranus rolls around the Sun with its poles nearly lying in the plane of its orbit."},{"id":"q7","question":"Which body was reclassified from planet to dwarf planet in 2006?","options":[{"id":"a","text":"Ceres","is_correct":false},{"id":"b","text":"Eris","is_correct":false},{"id":"c","text":"Pluto","is_correct":true},{"id":"d","text":"Haumea","is_correct":false}],"explanation":"The IAU definition left Pluto out because it does not clear its orbital neighbourhood."},{"id":"q8","question":"The main asteroid belt orbits between which two planets?","options":[{"id":"a","text":"Earth and Mars","is_correct":false},{"id":"b","text":"Mars and Jupiter","is_correct":true},{"id":"c","text":"Jupiter and Saturn","is_correct":false},{"id":"d","text":"Venus and Earth","is_correct":false}],"explanation":"The belt holds millions of rocky bodies between the orbits of Mars and Jupiter."}]'::jsonb,
  null,
