values (
  'es-trivia-planetas-del-sistema-solar',
  'Trivia del sistema solar: planetas, lunas y anillos',
  'Ocho preguntas sobre los planetas del sistema solar: cuál es el más grande, cuál el más caliente, quién luce los anillos y por qué Plutón salió de la lista.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué planeta está más cerca del Sol?","options":[{"id":"a","text":"Venus","is_correct":false},{"id":"b","text":"Mercurio","is_correct":true},{"id":"c","text":"La Tierra","is_correct":false},{"id":"d","text":"Marte","is_correct":false}],"explanation":"Mercurio completa una órbita en unos 88 días terrestres."},{"id":"q2","question":"¿Cuál es el planeta más grande del sistema solar?","options":[{"id":"a","text":"Saturno","is_correct":false},{"id":"b","text":"Júpiter","is_correct":true},{"id":"c","text":"Neptuno","is_correct":false},{"id":"d","text":"La Tierra","is_correct":false}],"explanation":"Júpiter tiene más masa que todos los demás planetas juntos."},{"id":"q3","question":"¿Qué planeta es conocido como el planeta rojo?","options":[{"id":"a","text":"Marte","is_correct":true},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Mercurio","is_correct":false},{"id":"d","text":"Júpiter","is_correct":false}],"explanation":"El polvo rico en óxido de hierro le da a Marte su color rojizo."},{"id":"q4","question":"¿Qué planeta es famoso por sus anillos brillantes y fáciles de ver?","options":[{"id":"a","text":"Júpiter","is_correct":false},{"id":"b","text":"Saturno","is_correct":true},{"id":"c","text":"Urano","is_correct":false},{"id":"d","text":"Neptuno","is_correct":false}],"explanation":"Otros gigantes tienen anillos tenues, pero los de Saturno son de hielo y se ven con un telescopio pequeño."},{"id":"q5","question":"¿Cuál es el planeta más caliente del sistema solar?","options":[{"id":"a","text":"Mercurio","is_correct":false},{"id":"b","text":"Venus","is_correct":true},{"id":"c","text":"Marte","is_correct":false},{"id":"d","text":"Júpiter","is_correct":false}],"explanation":"Venus atrapa el calor con una atmósfera densa de dióxido de carbono: su superficie llega a unos 465 °C."},{"id":"q6","question":"¿Qué planeta gira de lado, con el eje inclinado unos 98 grados?","options":[{"id":"a","text":"Neptuno","is_correct":false},{"id":"b","text":"Urano","is_correct":true},{"id":"c","text":"Saturno","is_correct":false},{"id":"d","text":"La Tierra","is_correct":false}],"explanation":"Urano rueda alrededor del Sol con los polos casi en el plano de su órbita."},{"id":"q7","question":"¿Qué cuerpo pasó de planeta a planeta enano en 2006?","options":[{"id":"a","text":"Ceres","is_correct":false},{"id":"b","text":"Eris","is_correct":false},{"id":"c","text":"Plutón","is_correct":true},{"id":"d","text":"Haumea","is_correct":false}],"explanation":"La definición de la UAI dejó fuera a Plutón porque no despeja su vecindad orbital."},{"id":"q8","question":"¿Entre qué dos planetas orbita el cinturón principal de asteroides?","options":[{"id":"a","text":"La Tierra y Marte","is_correct":false},{"id":"b","text":"Marte y Júpiter","is_correct":true},{"id":"c","text":"Júpiter y Saturno","is_correct":false},{"id":"d","text":"Venus y la Tierra","is_correct":false}],"explanation":"El cinturón reúne millones de cuerpos rocosos entre las órbitas de Marte y Júpiter."}]'::jsonb,
  null,
  array['ciencia', 'espacio', 'planetas', 'sistema solar', 'astronomía']::text[],
