insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-everyday-chemistry-trivia',
  'Everyday Chemistry Trivia: Kitchen, Cleaning, Materials',
  'Eight questions on the chemistry of daily life: what vinegar does to limescale, why cut apples turn brown and what a pH of 7 means.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the chemical formula of water?","options":[{"id":"a","text":"CO2","is_correct":false},{"id":"b","text":"H2O","is_correct":true},{"id":"c","text":"O2","is_correct":false},{"id":"d","text":"NaCl","is_correct":false}],"explanation":"Two hydrogen atoms and one oxygen atom make a water molecule."},{"id":"q2","question":"What gas is released when vinegar reacts with baking soda?","options":[{"id":"a","text":"Oxygen","is_correct":false},{"id":"b","text":"Carbon dioxide","is_correct":true},{"id":"c","text":"Hydrogen","is_correct":false},{"id":"d","text":"Chlorine","is_correct":false}],"explanation":"The acid-base reaction releases CO2, which is why the mix fizzes."},{"id":"q3","question":"What pH value is considered neutral?","options":[{"id":"a","text":"0","is_correct":false},{"id":"b","text":"3","is_correct":false},{"id":"c","text":"7","is_correct":true},{"id":"d","text":"14","is_correct":false}],"explanation":"Below 7 is acidic and above 7 is basic; pure water sits at 7."},{"id":"q4","question":"What is the chemical name of common table salt?","options":[{"id":"a","text":"Sodium chloride","is_correct":true},{"id":"b","text":"Calcium carbonate","is_correct":false},{"id":"c","text":"Potassium iodide","is_correct":false},{"id":"d","text":"Sodium bicarbonate","is_correct":false}],"explanation":"NaCl: one sodium atom for each chlorine atom."},{"id":"q5","question":"Why does a cut apple turn brown in the air?","options":[{"id":"a","text":"It loses water to the air","is_correct":false},{"id":"b","text":"Oxygen reacts with enzymes in the fruit","is_correct":true},{"id":"c","text":"Bacteria ferment its sugars","is_correct":false},{"id":"d","text":"Sunlight bleaches the surface","is_correct":false}],"explanation":"The oxidation can be slowed down with a little lemon juice."},{"id":"q6","question":"Which two things does iron need in order to rust?","options":[{"id":"a","text":"Oxygen and water","is_correct":true},{"id":"b","text":"Salt and vinegar","is_correct":false},{"id":"c","text":"Heat and sunlight","is_correct":false},{"id":"d","text":"Carbon dioxide and nitrogen","is_correct":false}],"explanation":"Rust is iron oxide; salt only speeds the process up."},{"id":"q7","question":"Why does vinegar remove limescale from a kettle?","options":[{"id":"a","text":"Its acid dissolves the mineral deposits","is_correct":true},{"id":"b","text":"It boils at a lower temperature than water","is_correct":false},{"id":"c","text":"It releases chlorine gas","is_correct":false},{"id":"d","text":"It is strongly alkaline","is_correct":false}],"explanation":"Limescale is mostly calcium carbonate, which dissolves in acetic acid."},{"id":"q8","question":"Which metal is liquid at room temperature?","options":[{"id":"a","text":"Iron","is_correct":false},{"id":"b","text":"Aluminium","is_correct":false},{"id":"c","text":"Mercury","is_correct":true},{"id":"d","text":"Copper","is_correct":false}],"explanation":"Mercury melts at about −39 °C, so it is liquid in most rooms."}]'::jsonb,
  null,
  array['science', 'chemistry', 'everyday life', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
