values (
  'es-trivia-quimica-de-lo-cotidiano',
  'Trivia de química cotidiana: cocina, limpieza y materiales',
  'Ocho preguntas sobre la química de la vida diaria: qué hace el vinagre con el sarro, por qué se oscurece la manzana cortada y qué significa un pH de 7.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuál es la fórmula química del agua?","options":[{"id":"a","text":"CO2","is_correct":false},{"id":"b","text":"H2O","is_correct":true},{"id":"c","text":"O2","is_correct":false},{"id":"d","text":"NaCl","is_correct":false}],"explanation":"Dos átomos de hidrógeno y uno de oxígeno forman una molécula de agua."},{"id":"q2","question":"¿Qué gas se libera cuando el vinagre reacciona con el bicarbonato de sodio?","options":[{"id":"a","text":"Oxígeno","is_correct":false},{"id":"b","text":"Dióxido de carbono","is_correct":true},{"id":"c","text":"Hidrógeno","is_correct":false},{"id":"d","text":"Cloro","is_correct":false}],"explanation":"La reacción ácido-base libera CO2, por eso la mezcla efervesce."},{"id":"q3","question":"¿Qué valor de pH se considera neutro?","options":[{"id":"a","text":"0","is_correct":false},{"id":"b","text":"3","is_correct":false},{"id":"c","text":"7","is_correct":true},{"id":"d","text":"14","is_correct":false}],"explanation":"Por debajo de 7 es ácido y por encima es básico; el agua pura está en 7."},{"id":"q4","question":"¿Cuál es el nombre químico de la sal de mesa común?","options":[{"id":"a","text":"Cloruro de sodio","is_correct":true},{"id":"b","text":"Carbonato de calcio","is_correct":false},{"id":"c","text":"Yoduro de potasio","is_correct":false},{"id":"d","text":"Bicarbonato de sodio","is_correct":false}],"explanation":"NaCl: un átomo de sodio por cada átomo de cloro."},{"id":"q5","question":"¿Por qué una manzana cortada se pone marrón al aire?","options":[{"id":"a","text":"Pierde agua hacia el aire","is_correct":false},{"id":"b","text":"El oxígeno reacciona con enzimas de la fruta","is_correct":true},{"id":"c","text":"Las bacterias fermentan sus azúcares","is_correct":false},{"id":"d","text":"La luz solar decolora la superficie","is_correct":false}],"explanation":"La oxidación se puede frenar con un poco de jugo de limón."},{"id":"q6","question":"¿Qué dos cosas necesita el hierro para oxidarse?","options":[{"id":"a","text":"Oxígeno y agua","is_correct":true},{"id":"b","text":"Sal y vinagre","is_correct":false},{"id":"c","text":"Calor y luz solar","is_correct":false},{"id":"d","text":"Dióxido de carbono y nitrógeno","is_correct":false}],"explanation":"La herrumbre es óxido de hierro; la sal solo acelera el proceso."},{"id":"q7","question":"¿Por qué el vinagre quita el sarro de una tetera?","options":[{"id":"a","text":"Su ácido disuelve los depósitos minerales","is_correct":true},{"id":"b","text":"Hierve a menor temperatura que el agua","is_correct":false},{"id":"c","text":"Libera gas cloro","is_correct":false},{"id":"d","text":"Es fuertemente alcalino","is_correct":false}],"explanation":"El sarro es sobre todo carbonato de calcio, que se disuelve en el ácido acético."},{"id":"q8","question":"¿Qué metal es líquido a temperatura ambiente?","options":[{"id":"a","text":"Hierro","is_correct":false},{"id":"b","text":"Aluminio","is_correct":false},{"id":"c","text":"Mercurio","is_correct":true},{"id":"d","text":"Cobre","is_correct":false}],"explanation":"El mercurio funde a unos −39 °C, así que es líquido en la mayoría de las habitaciones."}]'::jsonb,
  null,
  array['ciencia', 'química', 'vida cotidiana', 'trivia']::text[],
  3,
  'published',
