insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-chess-trivia',
  'Chess Trivia: Pieces, Rules and Famous Openings',
  'Eight questions on chess fundamentals: how the pieces move, what checkmate means and the openings every player should know by name.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"How many squares are there on a chessboard?","options":[{"id":"a","text":"48","is_correct":false},{"id":"b","text":"60","is_correct":false},{"id":"c","text":"64","is_correct":true},{"id":"d","text":"72","is_correct":false}],"explanation":"Eight ranks by eight files."},{"id":"q2","question":"How many pieces does each player start with?","options":[{"id":"a","text":"12","is_correct":false},{"id":"b","text":"14","is_correct":false},{"id":"c","text":"16","is_correct":true},{"id":"d","text":"20","is_correct":false}],"explanation":"Eight pawns, two rooks, two knights, two bishops, a queen and a king."},{"id":"q3","question":"Which piece can only move diagonally?","options":[{"id":"a","text":"The rook","is_correct":false},{"id":"b","text":"The bishop","is_correct":true},{"id":"c","text":"The queen","is_correct":false},{"id":"d","text":"The knight","is_correct":false}],"explanation":"Each bishop stays on the color it started on."},{"id":"q4","question":"Which piece moves in an L shape and can jump over others?","options":[{"id":"a","text":"The bishop","is_correct":false},{"id":"b","text":"The knight","is_correct":true},{"id":"c","text":"The queen","is_correct":false},{"id":"d","text":"The rook","is_correct":false}],"explanation":"Two squares in one direction, then one to the side."},{"id":"q5","question":"What is it called when the king is attacked and has no legal escape?","options":[{"id":"a","text":"Stalemate","is_correct":false},{"id":"b","text":"Check","is_correct":false},{"id":"c","text":"Checkmate","is_correct":true},{"id":"d","text":"Draw","is_correct":false}],"explanation":"Stalemate is a draw: no legal move, but the king is not under attack."},{"id":"q6","question":"Which special move moves the king two squares toward a rook?","options":[{"id":"a","text":"En passant","is_correct":false},{"id":"b","text":"Promotion","is_correct":false},{"id":"c","text":"Castling","is_correct":true},{"id":"d","text":"Fianchetto","is_correct":false}],"explanation":"It is the only move that shifts two pieces at once, and only if neither has moved before."},{"id":"q7","question":"What happens when a pawn reaches the last rank?","options":[{"id":"a","text":"It is removed from the board","is_correct":false},{"id":"b","text":"It can move backwards","is_correct":false},{"id":"c","text":"It must be promoted to another piece","is_correct":true},{"id":"d","text":"The game ends in a draw","is_correct":false}],"explanation":"The pawn is almost always promoted to a queen."},{"id":"q8","question":"Which opening is also known as the Spanish Opening?","options":[{"id":"a","text":"Sicilian Defense","is_correct":false},{"id":"b","text":"Queen''s Gambit","is_correct":false},{"id":"c","text":"Ruy López","is_correct":true},{"id":"d","text":"Italian Game","is_correct":false}],"explanation":"It begins 1.e4 e5 2.Nf3 Nc6 3.Bb5 and is named after a 16th-century Spanish priest."}]'::jsonb,
  null,
  array['chess', 'sports', 'board games', 'strategy', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
