values (
  'es-trivia-ajedrez',
  'Trivia de ajedrez: piezas, reglas y aperturas famosas',
  'Ocho preguntas sobre los fundamentos del ajedrez: cómo se mueven las piezas, qué es el jaque mate y las aperturas que todo jugador debería conocer.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Cuántas casillas tiene un tablero de ajedrez?","options":[{"id":"a","text":"48","is_correct":false},{"id":"b","text":"60","is_correct":false},{"id":"c","text":"64","is_correct":true},{"id":"d","text":"72","is_correct":false}],"explanation":"Ocho filas por ocho columnas."},{"id":"q2","question":"¿Con cuántas piezas empieza cada jugador?","options":[{"id":"a","text":"12","is_correct":false},{"id":"b","text":"14","is_correct":false},{"id":"c","text":"16","is_correct":true},{"id":"d","text":"20","is_correct":false}],"explanation":"Ocho peones, dos torres, dos caballos, dos alfiles, una dama y un rey."},{"id":"q3","question":"¿Qué pieza solo se mueve en diagonal?","options":[{"id":"a","text":"La torre","is_correct":false},{"id":"b","text":"El alfil","is_correct":true},{"id":"c","text":"La dama","is_correct":false},{"id":"d","text":"El caballo","is_correct":false}],"explanation":"Cada alfil se queda en el color en el que empezó."},{"id":"q4","question":"¿Qué pieza se mueve en forma de L y puede saltar sobre las demás?","options":[{"id":"a","text":"El alfil","is_correct":false},{"id":"b","text":"El caballo","is_correct":true},{"id":"c","text":"La dama","is_correct":false},{"id":"d","text":"La torre","is_correct":false}],"explanation":"Dos casillas en una dirección y una hacia el lado."},{"id":"q5","question":"¿Cómo se llama la posición en la que el rey está atacado y no tiene escapatoria legal?","options":[{"id":"a","text":"Ahogado","is_correct":false},{"id":"b","text":"Jaque","is_correct":false},{"id":"c","text":"Jaque mate","is_correct":true},{"id":"d","text":"Tablas","is_correct":false}],"explanation":"El ahogado es tablas: no hay jugada legal, pero el rey no está atacado."},{"id":"q6","question":"¿Qué jugada especial mueve al rey dos casillas hacia una torre?","options":[{"id":"a","text":"La captura al paso","is_correct":false},{"id":"b","text":"La coronación","is_correct":false},{"id":"c","text":"El enroque","is_correct":true},{"id":"d","text":"El fianchetto","is_correct":false}],"explanation":"Es la única jugada que mueve dos piezas a la vez, y solo si ninguna se ha movido antes."},{"id":"q7","question":"¿Qué ocurre cuando un peón llega a la última fila?","options":[{"id":"a","text":"Sale del tablero","is_correct":false},{"id":"b","text":"Puede moverse hacia atrás","is_correct":false},{"id":"c","text":"Debe coronar en otra pieza","is_correct":true},{"id":"d","text":"La partida termina en tablas","is_correct":false}],"explanation":"Casi siempre se corona en dama."},{"id":"q8","question":"¿Qué apertura se conoce también como apertura española?","options":[{"id":"a","text":"La defensa siciliana","is_correct":false},{"id":"b","text":"El gambito de dama","is_correct":false},{"id":"c","text":"La Ruy López","is_correct":true},{"id":"d","text":"La apertura italiana","is_correct":false}],"explanation":"Empieza con 1.e4 e5 2.Cf3 Cc6 3.Ab5 y lleva el nombre de un sacerdote español del siglo XVI."}]'::jsonb,
  null,
  array['ajedrez', 'deportes', 'juegos de mesa', 'estrategia', 'trivia']::text[],
  3,
  'published',
