values (
  'en-aviation-history-trivia',
  'Aviation History Trivia: From Kitty Hawk to the Jet Age',
  'Eight questions on the history of flight: the Wright brothers, the first solo Atlantic crossing, the first jet airliner and Concorde.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Who made the first powered, controlled airplane flight in 1903?","options":[{"id":"a","text":"The Wright brothers","is_correct":true},{"id":"b","text":"Alberto Santos-Dumont","is_correct":false},{"id":"c","text":"Charles Lindbergh","is_correct":false},{"id":"d","text":"Otto Lilienthal","is_correct":false}],"explanation":"Orville flew the Flyer for 12 seconds near Kitty Hawk; Wilbur flew it further later that day."},{"id":"q2","question":"Where did the Wright brothers'' first flight take place?","options":[{"id":"a","text":"Dayton, Ohio","is_correct":false},{"id":"b","text":"Kitty Hawk, North Carolina","is_correct":true},{"id":"c","text":"Cape Canaveral, Florida","is_correct":false},{"id":"d","text":"Langley, Virginia","is_correct":false}],"explanation":"They chose the Outer Banks for its steady winds and soft sand."},{"id":"q3","question":"Who was the first person to fly solo nonstop across the Atlantic?","options":[{"id":"a","text":"Amelia Earhart","is_correct":false},{"id":"b","text":"Charles Lindbergh","is_correct":true},{"id":"c","text":"Howard Hughes","is_correct":false},{"id":"d","text":"Wiley Post","is_correct":false}],"explanation":"He flew from New York to Paris in about 33 hours, in 1927."},{"id":"q4","question":"What was the name of Charles Lindbergh''s airplane?","options":[{"id":"a","text":"Enola Gay","is_correct":false},{"id":"b","text":"Spirit of St. Louis","is_correct":true},{"id":"c","text":"Spruce Goose","is_correct":false},{"id":"d","text":"Memphis Belle","is_correct":false}],"explanation":"The single-engine Ryan monoplane was named for the city that financed it."},{"id":"q5","question":"Who was the first woman to fly solo across the Atlantic?","options":[{"id":"a","text":"Amelia Earhart","is_correct":true},{"id":"b","text":"Harriet Quimby","is_correct":false},{"id":"c","text":"Bessie Coleman","is_correct":false},{"id":"d","text":"Jacqueline Cochran","is_correct":false}],"explanation":"She crossed in 1932, five years after Lindbergh."},{"id":"q6","question":"Which aircraft flew the first scheduled commercial jet service in 1952?","options":[{"id":"a","text":"Boeing 707","is_correct":false},{"id":"b","text":"Douglas DC-8","is_correct":false},{"id":"c","text":"de Havilland Comet","is_correct":true},{"id":"d","text":"Concorde","is_correct":false}],"explanation":"The Comet flew from London to Johannesburg with BOAC."},{"id":"q7","question":"What was the Concorde famous for?","options":[{"id":"a","text":"Being the first jet airliner","is_correct":false},{"id":"b","text":"Being a supersonic passenger airliner","is_correct":true},{"id":"c","text":"Being the largest cargo plane ever built","is_correct":false},{"id":"d","text":"Making the first Atlantic crossing","is_correct":false}],"explanation":"It cruised at twice the speed of sound and crossed the Atlantic in about three and a half hours."},{"id":"q8","question":"Which conflict saw the first large-scale military use of airplanes?","options":[{"id":"a","text":"World War I","is_correct":true},{"id":"b","text":"World War II","is_correct":false},{"id":"c","text":"The Korean War","is_correct":false},{"id":"d","text":"The Spanish Civil War","is_correct":false}],"explanation":"Planes went from scouting in 1914 to fighters and bombers by 1918."}]'::jsonb,
  null,
  array['aviation', 'history', 'airplanes', 'trivia', 'technology']::text[],
  3,
  'published',
  false,
  false,
  now()
)
