values (
  'es-trivia-historia-de-la-aviacion',
  'Trivia de historia de la aviación: de Kitty Hawk al jet',
  'Ocho preguntas sobre la historia del vuelo: los hermanos Wright, el primer cruce del Atlántico en solitario, el primer avión a reacción comercial y el Concorde.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Quién realizó el primer vuelo controlado en un avión a motor, en 1903?","options":[{"id":"a","text":"Los hermanos Wright","is_correct":true},{"id":"b","text":"Alberto Santos-Dumont","is_correct":false},{"id":"c","text":"Charles Lindbergh","is_correct":false},{"id":"d","text":"Otto Lilienthal","is_correct":false}],"explanation":"Orville voló el Flyer durante 12 segundos cerca de Kitty Hawk; Wilbur llegó más lejos ese mismo día."},{"id":"q2","question":"¿Dónde tuvo lugar el primer vuelo de los hermanos Wright?","options":[{"id":"a","text":"Dayton, Ohio","is_correct":false},{"id":"b","text":"Kitty Hawk, Carolina del Norte","is_correct":true},{"id":"c","text":"Cabo Cañaveral, Florida","is_correct":false},{"id":"d","text":"Langley, Virginia","is_correct":false}],"explanation":"Eligieron los Outer Banks por sus vientos constantes y su arena suave."},{"id":"q3","question":"¿Quién fue la primera persona en volar en solitario y sin escalas a través del Atlántico?","options":[{"id":"a","text":"Amelia Earhart","is_correct":false},{"id":"b","text":"Charles Lindbergh","is_correct":true},{"id":"c","text":"Howard Hughes","is_correct":false},{"id":"d","text":"Wiley Post","is_correct":false}],"explanation":"Voló de Nueva York a París en unas 33 horas, en 1927."},{"id":"q4","question":"¿Cómo se llamaba el avión de Charles Lindbergh?","options":[{"id":"a","text":"Enola Gay","is_correct":false},{"id":"b","text":"Spirit of St. Louis","is_correct":true},{"id":"c","text":"Spruce Goose","is_correct":false},{"id":"d","text":"Memphis Belle","is_correct":false}],"explanation":"El monoplano Ryan de un solo motor llevaba el nombre de la ciudad que lo financió."},{"id":"q5","question":"¿Quién fue la primera mujer en volar en solitario a través del Atlántico?","options":[{"id":"a","text":"Amelia Earhart","is_correct":true},{"id":"b","text":"Harriet Quimby","is_correct":false},{"id":"c","text":"Bessie Coleman","is_correct":false},{"id":"d","text":"Jacqueline Cochran","is_correct":false}],"explanation":"Cruzó en 1932, cinco años después de Lindbergh."},{"id":"q6","question":"¿Qué avión realizó el primer servicio comercial regular a reacción, en 1952?","options":[{"id":"a","text":"Boeing 707","is_correct":false},{"id":"b","text":"Douglas DC-8","is_correct":false},{"id":"c","text":"de Havilland Comet","is_correct":true},{"id":"d","text":"Concorde","is_correct":false}],"explanation":"El Comet voló de Londres a Johannesburgo con BOAC."},{"id":"q7","question":"¿Por qué era famoso el Concorde?","options":[{"id":"a","text":"Por ser el primer avión a reacción","is_correct":false},{"id":"b","text":"Por ser un avión de pasajeros supersónico","is_correct":true},{"id":"c","text":"Por ser el avión de carga más grande jamás construido","is_correct":false},{"id":"d","text":"Por hacer el primer cruce del Atlántico","is_correct":false}],"explanation":"Volaba a dos veces la velocidad del sonido y cruzaba el Atlántico en unas tres horas y media."},{"id":"q8","question":"¿Qué conflicto vio el primer uso militar a gran escala de los aviones?","options":[{"id":"a","text":"La Primera Guerra Mundial","is_correct":true},{"id":"b","text":"La Segunda Guerra Mundial","is_correct":false},{"id":"c","text":"La Guerra de Corea","is_correct":false},{"id":"d","text":"La Guerra Civil española","is_correct":false}],"explanation":"Los aviones pasaron del reconocimiento en 1914 a cazas y bombarderos en 1918."}]'::jsonb,
  null,
  array['aviación', 'historia', 'aviones', 'trivia', 'tecnología']::text[],
