insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-nutrition-basics-trivia',
  'Nutrition Trivia: Nutrients, Food Groups and Myths',
  'Eight questions on basic nutrition: what carbohydrates, proteins and fats do, where fiber comes from and the vitamins behind everyday advice.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"Which nutrient group is the body''s main source of quick energy?","options":[{"id":"a","text":"Proteins","is_correct":false},{"id":"b","text":"Carbohydrates","is_correct":true},{"id":"c","text":"Vitamins","is_correct":false},{"id":"d","text":"Minerals","is_correct":false}],"explanation":"Carbohydrates break down into glucose, the fuel cells burn first."},{"id":"q2","question":"Proteins are built from smaller units called…","options":[{"id":"a","text":"fatty acids","is_correct":false},{"id":"b","text":"amino acids","is_correct":true},{"id":"c","text":"glucose chains","is_correct":false},{"id":"d","text":"nucleotides","is_correct":false}],"explanation":"The body uses about twenty amino acids; nine are essential and come from food."},{"id":"q3","question":"Which vitamin does the skin produce when exposed to sunlight?","options":[{"id":"a","text":"Vitamin A","is_correct":false},{"id":"b","text":"Vitamin C","is_correct":false},{"id":"c","text":"Vitamin D","is_correct":true},{"id":"d","text":"Vitamin B12","is_correct":false}],"explanation":"UVB light triggers the synthesis; the rest of the intake usually comes from food."},{"id":"q4","question":"Which of these foods is the best source of dietary fiber?","options":[{"id":"a","text":"White rice","is_correct":false},{"id":"b","text":"Lentils","is_correct":true},{"id":"c","text":"Butter","is_correct":false},{"id":"d","text":"Cheese","is_correct":false}],"explanation":"Legumes combine fiber with plant protein; animal foods contain no fiber."},{"id":"q5","question":"Which mineral is most associated with strong bones and teeth?","options":[{"id":"a","text":"Iron","is_correct":false},{"id":"b","text":"Calcium","is_correct":true},{"id":"c","text":"Sodium","is_correct":false},{"id":"d","text":"Potassium","is_correct":false}],"explanation":"Dairy, leafy greens and fortified foods are common sources."},{"id":"q6","question":"What does the body need iron for?","options":[{"id":"a","text":"Storing energy as fat","is_correct":false},{"id":"b","text":"Making hemoglobin to carry oxygen in the blood","is_correct":true},{"id":"c","text":"Producing vitamin C","is_correct":false},{"id":"d","text":"Building cell walls","is_correct":false}],"explanation":"Low iron is the most common nutrient deficiency worldwide."},{"id":"q7","question":"Citrus fruits are famous for which vitamin?","options":[{"id":"a","text":"Vitamin C","is_correct":true},{"id":"b","text":"Vitamin D","is_correct":false},{"id":"c","text":"Vitamin B12","is_correct":false},{"id":"d","text":"Vitamin K","is_correct":false}],"explanation":"Vitamin C supports the immune system and collagen formation."},{"id":"q8","question":"What does the color of an eggshell actually indicate?","options":[{"id":"a","text":"Its nutritional value","is_correct":false},{"id":"b","text":"The breed of the hen","is_correct":true},{"id":"c","text":"How fresh the egg is","is_correct":false},{"id":"d","text":"Its cholesterol content","is_correct":false}],"explanation":"Brown and white eggs are nutritionally near-identical; the shell color comes from the hen''s breed."}]'::jsonb,
  null,
  array['nutrition', 'food', 'health', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-nutricion-y-alimentacion',
  'Trivia de nutrición: nutrientes, grupos de alimentos y mitos',
  'Ocho preguntas sobre nutrición básica: qué hacen los carbohidratos, las proteínas y las grasas, de dónde sale la fibra y las vitaminas detrás de los consejos de siempre.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"¿Qué grupo de nutrientes es la principal fuente de energía rápida del cuerpo?","options":[{"id":"a","text":"Las proteínas","is_correct":false},{"id":"b","text":"Los carbohidratos","is_correct":true},{"id":"c","text":"Las vitaminas","is_correct":false},{"id":"d","text":"Los minerales","is_correct":false}],"explanation":"Los carbohidratos se convierten en glucosa, el combustible que las células queman primero."},{"id":"q2","question":"Las proteínas están formadas por unidades más pequeñas llamadas…","options":[{"id":"a","text":"ácidos grasos","is_correct":false},{"id":"b","text":"aminoácidos","is_correct":true},{"id":"c","text":"cadenas de glucosa","is_correct":false},{"id":"d","text":"nucleótidos","is_correct":false}],"explanation":"El cuerpo usa unos veinte aminoácidos; nueve son esenciales y salen de los alimentos."},{"id":"q3","question":"¿Qué vitamina produce la piel al exponerse a la luz solar?","options":[{"id":"a","text":"La vitamina A","is_correct":false},{"id":"b","text":"La vitamina C","is_correct":false},{"id":"c","text":"La vitamina D","is_correct":true},{"id":"d","text":"La vitamina B12","is_correct":false}],"explanation":"La luz UVB activa la síntesis; el resto del aporte suele venir de los alimentos."},{"id":"q4","question":"¿Cuál de estos alimentos es la mejor fuente de fibra dietética?","options":[{"id":"a","text":"El arroz blanco","is_correct":false},{"id":"b","text":"Las lentejas","is_correct":true},{"id":"c","text":"La mantequilla","is_correct":false},{"id":"d","text":"El queso","is_correct":false}],"explanation":"Las legumbres combinan fibra con proteína vegetal; los alimentos de origen animal no tienen fibra."},{"id":"q5","question":"¿Qué mineral se asocia más con huesos y dientes fuertes?","options":[{"id":"a","text":"El hierro","is_correct":false},{"id":"b","text":"El calcio","is_correct":true},{"id":"c","text":"El sodio","is_correct":false},{"id":"d","text":"El potasio","is_correct":false}],"explanation":"Los lácteos, las hojas verdes y los alimentos fortificados son fuentes comunes."},{"id":"q6","question":"¿Para qué necesita el cuerpo el hierro?","options":[{"id":"a","text":"Para almacenar energía como grasa","is_correct":false},{"id":"b","text":"Para producir hemoglobina que transporta oxígeno en la sangre","is_correct":true},{"id":"c","text":"Para producir vitamina C","is_correct":false},{"id":"d","text":"Para construir paredes celulares","is_correct":false}],"explanation":"El hierro bajo es la deficiencia de nutrientes más común del mundo."},{"id":"q7","question":"¿Por qué vitamina son famosos los cítricos?","options":[{"id":"a","text":"La vitamina C","is_correct":true},{"id":"b","text":"La vitamina D","is_correct":false},{"id":"c","text":"La vitamina B12","is_correct":false},{"id":"d","text":"La vitamina K","is_correct":false}],"explanation":"La vitamina C apoya el sistema inmunitario y la formación de colágeno."},{"id":"q8","question":"¿Qué indica en realidad el color del cascarón de un huevo?","options":[{"id":"a","text":"Su valor nutricional","is_correct":false},{"id":"b","text":"La raza de la gallina","is_correct":true},{"id":"c","text":"Qué tan fresco está","is_correct":false},{"id":"d","text":"Su contenido de colesterol","is_correct":false}],"explanation":"Los huevos marrones y blancos son nutricionalmente casi idénticos; el color viene de la raza de la gallina."}]'::jsonb,
  null,
  array['nutrición', 'comida', 'salud', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

